<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_login();
$aid=get_int('id');$s=db()->prepare('SELECT a.*,e.title exam_title,u.full_name student_name FROM attempts a JOIN exams e ON e.id=a.exam_id JOIN users u ON u.id=a.student_id WHERE a.id=?');$s->execute([$aid]);$attempt=$s->fetch();if(!$attempt)exit('گزارش پیدا نشد.');$u=current_user();if($u['role']==='student'&&(int)$attempt['student_id']!==(int)$u['id'])exit('مجوز ندارید.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$token=bin2hex(random_bytes(32));$days=max(1,min(30,(int)($_POST['days']??7)));$expires=date('Y-m-d H:i:s',time()+($days*86400));$s=db()->prepare('INSERT INTO report_shares(attempt_id,token,expires_at,created_by) VALUES(?,?,?,?)');$s->execute([$aid,$token,$expires,$u['id']]);$created=url('reports/view.php?token='.$token);flash('success','لینک گزارش ایجاد شد: '.$created);}
$title='اشتراک گزارش';require __DIR__.'/../partials/header.php';?><div class="card"><h1>اشتراک گزارش</h1><p>گزارش آزمون <strong><?=e($attempt['exam_title'])?></strong> برای <?=e($attempt['student_name'])?></p><form method="post"><?=csrf_field()?><div class="form-group"><label>اعتبار لینک (روز)</label><input type="number" name="days" value="7" min="1" max="30"></div><button class="btn btn-primary">ایجاد لینک</button></form><?php if(!empty($created)):?><div class="alert success" style="margin-top:20px"><input value="<?=e($created)?>" readonly onclick="this.select()"></div><?php endif;?></div><?php require __DIR__.'/../partials/footer.php'; ?>
